/// Proposes transition values. A Core refusal or a record that does not fit the relation's
/// shape is a refusal to propose, never a "false" claim.
pub fn propose_values(relation: &CompiledRelation, transition: &TransitionInput) -> Result<TransitionValues, DriverError> {
    match transition {
        TransitionInput::CoreReference { scenario } => witness::propose(relation, scenario, None).map_err(DriverError::Proposal),
        TransitionInput::Records { inputs, pre, post, effects } => {
            witness::from_records(relation.plan(), inputs, pre, post, effects, None).map_err(DriverError::Proposal)
        }
    }
}

pub fn propose(relation: &CompiledRelation, scenario: &Scenario, cap: Option<UInt>) -> Result<TransitionValues, MappingError> {
    let program = relation.program();
    let action = relation.plan().action.as_str();
    let execution = match (relation.plan().cap, cap) {
        (CapBinding::NotBound, None) => mori_core::simulate(program, action, scenario).map_err(MappingError::ReferenceRefused)?,
        (CapBinding::PublicCap, Some(c)) => {
            mori_core::simulate_metered(program, action, scenario, c).map_err(|refused| MappingError::ReferenceRefused(refused.error))?.execution
        }
        (CapBinding::PublicCap, None) => return Err(MappingError::Cap("relation binds a public cap; supply one".into())),
        (CapBinding::NotBound, Some(_)) => return Err(MappingError::Cap("relation binds no cap".into())),
    };
    from_execution(relation, scenario, &execution, cap)
}

/// Maps an `Execution` (reference output or frozen oracle record) for `relation`.
pub fn from_execution(relation: &CompiledRelation, scenario: &Scenario, execution: &Execution, cap: Option<UInt>) -> Result<TransitionValues, MappingError> {
    if execution.action != relation.plan().action || execution.semantics != mori_core::SEMANTICS {
        return Err(MappingError::Shape("execution names another action or semantics".into()));
    }
    from_records(relation.plan(), &scenario.inputs, &execution.pre, &execution.post, &execution.effects, cap)
}

pub fn from_records(
    plan: &ActionPlan,
    inputs: &BTreeMap<String, Value>,
    pre: &Snapshot,
    post: &Snapshot,
    effects: &[Effect],
    cap: Option<UInt>,
) -> Result<TransitionValues, MappingError> {
    if inputs.len() != plan.inputs.len() {
        return Err(MappingError::Shape("scenario inputs differ from the action's inputs".into()));
    }
    let mut claimed_inputs = Vec::with_capacity(plan.inputs.len());
    for i in &plan.inputs {
        let v = inputs.get(&i.name).ok_or_else(|| MappingError::Shape(format!("input {} missing", i.name)))?;
        if v.ty() != i.ty {
            return Err(MappingError::Shape(format!("input {} has the wrong type", i.name)));
        }
        claimed_inputs.push(v.clone());
    }
    frame_unchanged(plan, pre, post)?;
    if effects.len() != plan.effects.len() {
        return Err(MappingError::Shape(format!("record has {} effects, the action has {}", effects.len(), plan.effects.len())));
    }
    let mut claimed_effects = Vec::with_capacity(effects.len());
    for (index, (shape, e)) in plan.effects.iter().zip(effects).enumerate() {
        claimed_effects.push(effect(plan, index, shape, e)?);
    }
    match (plan.cap, cap) {
        (CapBinding::PublicCap, None) => return Err(MappingError::Cap("relation binds a public cap; supply one".into())),
        (CapBinding::NotBound, Some(_)) => return Err(MappingError::Cap("relation binds no cap".into())),
        _ => {}
    }
    Ok(TransitionValues {
        inputs: claimed_inputs,
        pre: body(plan, pre, "pre")?,
        post: body(plan, post, "post")?,
        effects: claimed_effects,
        cap,
    })
}

fn body(plan: &ActionPlan, snapshot: &Snapshot, phase: &str) -> Result<BodyValues, MappingError> {
    let mut states = Vec::with_capacity(plan.states.len());
    for s in &plan.states {
        let v = snapshot.state.get(&s.name).ok_or_else(|| MappingError::Shape(format!("{phase} state {} missing", s.name)))?;
        if v.ty() != s.ty {
            return Err(MappingError::Shape(format!("{phase} state {} has the wrong type", s.name)));
        }
        states.push(v.clone());
    }
    if snapshot.state.len() != plan.states.len() {
        return Err(MappingError::Shape(format!("{phase} snapshot carries undeclared states")));
    }
    let mut cells = Vec::with_capacity(plan.cells.len());
    for c in &plan.cells {
        let row = snapshot
            .balances
            .iter()
            .find(|b| b.asset == c.asset && b.account == c.account)
            .ok_or_else(|| MappingError::Shape(format!("{phase} balance {}/{} missing", c.asset_name, c.account)))?;
        cells.push(row.amount);
    }
    let mut duties = Vec::with_capacity(plan.duties.len());
    for d in &plan.duties {
        match snapshot.liabilities.iter().find(|l| l.name == d.name) {
            Some(l) => {
                if l.asset != d.asset || l.debtor != d.debtor || l.creditor != d.creditor {
                    return Err(MappingError::Shape(format!("{phase} duty {} identity differs from the source registry", d.name)));
                }
                duties.push(DutyValue { present: true, amount: l.amount });
            }
            None => duties.push(DutyValue { present: false, amount: UInt(0) }),
        }
    }
    Ok(BodyValues { states, cells, duties })
}

/// Rows outside the represented cells and registry must be identical before and after
/// (Core never changes them). Representing them is a target obligation.
fn frame_unchanged(plan: &ActionPlan, pre: &Snapshot, post: &Snapshot) -> Result<(), MappingError> {
    let represented = |asset: &mori_core::AssetId, account: &str| plan.cells.iter().any(|c| &c.asset == asset && c.account == account);
    let outside = |s: &Snapshot| -> BTreeSet<(mori_core::AssetId, String, UInt)> {
        s.balances.iter().filter(|b| !represented(&b.asset, &b.account)).map(|b| (b.asset.clone(), b.account.clone(), b.amount)).collect()
    };
    if outside(pre) != outside(post) {
        return Err(MappingError::FrameChanged("an unrepresented balance row differs between pre and post".into()));
    }
    let registry: BTreeSet<&str> = plan.duties.iter().map(|d| d.name.as_str()).collect();
    let rows = |s: &Snapshot| -> Vec<mori_core::Liability> {
        s.liabilities.iter().filter(|l| !registry.contains(l.name.as_str())).cloned().collect()
    };
    if rows(pre) != rows(post) {
        return Err(MappingError::FrameChanged("an unrepresented liability row differs between pre and post".into()));
    }
    Ok(())

fn effect(plan: &ActionPlan, index: usize, shape: &EffectShape, e: &Effect) -> Result<EffectValues, MappingError> {
    let mismatch = || MappingError::Shape(format!("effect {index} differs from its source shape"));
    Ok(match (shape, e) {
        (EffectShape::State { name, ty, .. }, Effect::State { name: n, before, after }) => {
            if n != name || before.ty() != *ty || after.ty() != *ty {
                return Err(mismatch());
            }
            EffectValues::State { before: before.clone(), after: after.clone() }
        }
        (EffectShape::Transfer { asset, from, to, .. }, Effect::Transfer { asset: a, from: f, to: t, amount })
        | (EffectShape::Fee { asset, from, to, .. }, Effect::Fee { asset: a, from: f, to: t, amount }) => {
            if a != asset || f != from || t != to {
                return Err(mismatch());
            }
            EffectValues::Amount(*amount)
        }
        (EffectShape::Liability { duty, name, .. }, Effect::Liability { name: n, asset, debtor, creditor, before, after }) => {
            let d = &plan.duties[*duty];
            if n != name || *asset != d.asset || *debtor != d.debtor || *creditor != d.creditor {
                return Err(mismatch());
            }
            EffectValues::Duty { before: *before, after: *after }
        }
        (EffectShape::Emit { name, ty, .. }, Effect::Emit { name: n, value }) => {
            if n != name || value.ty() != *ty {
                return Err(mismatch());
            }
            EffectValues::Emit(value.clone())
        }
        _ => return Err(mismatch()),
    })
}

/// Big-endian 128-bit halves of a 32-byte digest (`abi2.rs:297-305`).
pub fn digest_halves(d: &[u8; 32]) -> [u128; 2] {
    let mut hi = [0u8; 16];
    let mut lo = [0u8; 16];
    hi.copy_from_slice(&d[..16]);
    lo.copy_from_slice(&d[16..]);
    [u128::from_be_bytes(hi), u128::from_be_bytes(lo)]
}

pub fn claim_from_values(selected: &SelectedRelation, values: TransitionValues, ctx: ContextV2) -> Result<PreparedClaim, DriverError> {
    let relation = selected.relation();
    let statement = relation.statement_v2(&values, &ctx).map_err(DriverError::Proposal)?;
    if statement.len() > MAX_STATEMENT_BYTES {
        return Err(DriverError::Input(format!("statement of {} bytes exceeds {MAX_STATEMENT_BYTES}", statement.len())));
    }
    let statement_digest = mori_r1cs::blake2b::blake2b256(&statement);
    let public_inputs = digest_halves(&statement_digest);
    // The compiler's own public-input path must agree with the digest halves.
    let compiled = relation.public_inputs_v2::<Fr>(&values, &ctx).map_err(DriverError::Proposal)?;
    if compiled != vec![Fr::from(public_inputs[0]), Fr::from(public_inputs[1])] {
        return Err(DriverError::Backend("compiler public inputs differ from the statement digest halves".into()));
    }
    Ok(PreparedClaim { values, context: ctx, statement, statement_digest, public_inputs })
}

pub fn statement_v2(&self, values: &TransitionValues, context: &ContextV2) -> Result<Vec<u8>, MappingError> {
    let consts = self
        .abi2
        .as_ref()
        .ok_or(MappingError::Adapter(AdapterError::Unadopted("statement_v2 needs the SettlementHashV2 adapter")))?;
    crate::statement::check_values(&self.plan, values)?;
    let body = abi2::body_bytes(&self.layout, &self.plan, values)?;
    abi2::statement_bytes(consts, context, &body)
}

/// P3S1: the two ABI v2 public inputs of a claimed transition in a context.
pub fn public_inputs_v2<F: PrimeField>(&self, values: &TransitionValues, context: &ContextV2) -> Result<Vec<F>, MappingError> {
    self.check_field::<F>().map_err(MappingError::Field)?;
    Ok(abi2::public_inputs::<F>(&self.statement_v2(values, context)?))
}

/// P3S1: an ABI v2 assignment (public = the two digest halves).
pub fn assignment_v2<F: PrimeField>(&self, values: TransitionValues, context: &ContextV2) -> Result<Assignment<F>, MappingError> {
    let public = self.public_inputs_v2::<F>(&values, context)?;
    Ok(Assignment { values, public })
}

/// P3S1: an ABI v2 circuit for proving (assignment and context) or setup (neither).
pub fn circuit_v2<F: PrimeField>(
    &self,
    assignment: Option<Assignment<F>>,
    context: Option<ContextV2>,
    tamper: Tamper<F>,
) -> Result<TransitionCircuit<'_, F>, CompileError> {
    self.check_field::<F>().map_err(CompileError::Field)?;
    if self.adapter != StatementAdapter::SettlementHashV2 {
        return Err(CompileError::Option("circuit_v2 needs the SettlementHashV2 adapter".into()));
    }
    if assignment.is_some() != context.is_some() {
        return Err(CompileError::Option("SettlementHashV2 proving needs both an assignment and a ContextV2".into()));
    }
    if let Some(a) = &assignment {
        self.check_assignment_lengths(a)?;
    }
    Ok(TransitionCircuit { relation: self, assignment, context, tamper })
}

fn check_assignment_lengths<F: PrimeField>(&self, a: &Assignment<F>) -> Result<(), CompileError> {
    let plan = &self.plan;
    let body = |b: &BodyValues| -> bool {
        b.states.len() == plan.states.len() && b.cells.len() == plan.cells.len() && b.duties.len() == plan.duties.len()
    };
    let checks = [
        ("inputs", a.values.inputs.len() == plan.inputs.len()),
        ("pre body", body(&a.values.pre)),
        ("post body", body(&a.values.post)),
        ("effects", a.values.effects.len() == plan.effects.len()),
        ("public inputs", self.adapter.public_input_count(&self.layout).is_ok_and(|n| a.public.len() == n)),
    ];
    match checks.iter().find(|(_, ok)| !*ok) {
        Some((what, _)) => Err(CompileError::AssignmentShape(format!("{what} length differs from the relation"))),
        None => Ok(()),
    }
}

fn check_field<F: PrimeField>(&self) -> Result<(), String> {
    let modulus = hex_le(&F::MODULUS.to_bytes_le());
    if modulus != self.probe.field_modulus_le_hex {
        return Err("circuit field differs from the field the relation was compiled and probed in".into());
    }
    Ok(())
}

/// The constraint-system decision on a prepared claim. Needs no key.
pub fn check_claim(selected: &SelectedRelation, claim: &PreparedClaim) -> Result<SatisfiedClaim, DriverError> {
    let relation = selected.relation();
    let assignment = relation.assignment_v2::<Fr>(claim.values.clone(), &claim.context).map_err(DriverError::Proposal)?;
    let expected_public = vec![Fr::from(claim.public_inputs[0]), Fr::from(claim.public_inputs[1])];
    if assignment.public != expected_public {
        return Err(DriverError::Backend("assignment public inputs differ from the statement digest halves".into()));
    }
    let circuit = relation
        .circuit_v2::<Fr>(Some(assignment), Some(claim.context.clone()), Tamper::none())
        .map_err(DriverError::Compile)?;
    let cs = ConstraintSystem::<Fr>::new_ref();
    cs.set_optimization_goal(OptimizationGoal::Constraints);
    cs.set_mode(SynthesisMode::Prove { construct_matrices: true });
    let report = circuit.synthesize_into(cs.clone()).map_err(|e| DriverError::Backend(format!("synthesis: {e}")))?;

impl<F: PrimeField> TransitionCircuit<'_, F> {
    /// Synthesizes into `cs` and reports regions and tamper hits.
    pub fn synthesize_into(self, cs: ConstraintSystemRef<F>) -> Result<SynthesisReport, SynthesisError> {
        synthesize(self.relation, self.assignment.as_ref(), self.context.as_ref(), self.tamper, cs).map_err(SynthFailure::into_synthesis_error)
    }
}

impl<F: PrimeField> ConstraintSynthesizer<F> for TransitionCircuit<'_, F> {
    fn generate_constraints(self, cs: ConstraintSystemRef<F>) -> Result<(), SynthesisError> {
        self.synthesize_into(cs).map(|_| ())
    }

let report = circuit.synthesize_into(cs.clone()).map_err(|e| DriverError::Backend(format!("synthesis: {e}")))?;
if report.overrides_used != 0 {
    return Err(DriverError::Backend("a tamper override reached a witness in a production synthesis".into()));
}
match cs.is_satisfied() {
    Ok(true) => {}
    Ok(false) => {
        return Err(DriverError::Unsatisfied(
            "the compiled relation rejects this claimed transition in this context".into(),
        ));
    }
    Err(e) => return Err(DriverError::Backend(format!("satisfaction check: {e}"))),
}
cs.finalize();
let matrices = cs.to_matrices().ok_or_else(|| DriverError::Backend("prove-mode matrices were not constructed".into()))?;
let digest = relation::matrix_digest(&matrices);
let probe = relation.probe().r1cs_sha256;
if digest != probe {
    return Err(DriverError::mismatch("r1cs matrices (prove synthesis vs compile probe)", probe.hex(), digest.hex()));
}
let (full_assignment, num_inputs) = {
    let inner = cs.borrow().ok_or_else(|| DriverError::Backend("constraint system missing".into()))?;
    let full: Vec<Fr> = inner.instance_assignment.iter().chain(inner.witness_assignment.iter()).copied().collect();
    (full, inner.num_instance_variables)
};
let expected_instance = [Fr::one(), expected_public[0], expected_public[1]];
if num_inputs != 3 || full_assignment.len() < 3 || full_assignment[..3] != expected_instance[..] {
    return Err(DriverError::Backend("instance assignment is not [1, x1, x2]".into()));
}
let num_constraints = matrices.num_constraints;
Ok(SatisfiedClaim { matrices, full_assignment, num_inputs, num_constraints })

